#!/usr/bin/env python3
import subprocess
import shutil

# Try to find LAMMPS executable
lammps_names = ['lmp', 'lammps', 'lmp_serial', 'lmp_mpi']

for name in lammps_names:
    path = shutil.which(name)
    if path:
        print(f"Found LAMMPS: {name} at {path}")
    else:
        print(f"Not found: {name}")
